using UnityEngine;

namespace HimoHito
{
    // Render-only shoulder/elbow chains. Original head, body size and physics stay intact.
    public sealed class ActiveSwingArms : MonoBehaviour
    {
        LineRenderer left,right;Material yarn;
        float weight,releaseWeight,torso,travel=1;
        Vector4 angles=new Vector4(-28,-115,30,115);
        public string Phase {get;private set;}="hidden";
        public float Weight=>weight;
        public Vector4 Angles=>angles;
        public Vector3 LeftHand {get;private set;}
        public Vector3 RightHand {get;private set;}
        bool previouslyAttached;

        void Awake()
        {
            yarn=new Material(Shader.Find("Sprites/Default")){name="Gesture wool arms (display only)"};
            yarn.mainTexture=YarnRopeTexture.Load();
            left=Make("Left shoulder elbow hand");right=Make("Right shoulder elbow hand");
        }
        LineRenderer Make(string name)
        {
            var child=new GameObject(name);child.transform.SetParent(transform,false);
            var line=child.AddComponent<LineRenderer>();line.sharedMaterial=yarn;
            line.useWorldSpace=true;line.positionCount=3;line.numCapVertices=6;line.numCornerVertices=6;
            line.textureMode=LineTextureMode.Tile;line.enabled=false;return line;
        }
        public void Advance(bool attached,bool grounded,bool ready,float oldReleaseWeight,
            Vector2 velocity,float input,float bottom,float dt)
        {
            if(dt<=0)return;
            if(!attached)
            {
                if(previouslyAttached)releaseWeight=weight;
                weight=grounded?0:releaseWeight*oldReleaseWeight;
                Phase=weight>0?"release_handoff":"hidden";
                previouslyAttached=false;return;
            }
            previouslyAttached=true;
            if(Mathf.Abs(velocity.x)>.6f)travel=Mathf.Sign(velocity.x);
            bool pressing=Mathf.Abs(input)>.05f;
            bool braking=pressing&&input*velocity.x<-.35f;
            float speed=velocity.magnitude;
            Vector4 target;float lean=0;
            if(grounded){Phase="ground_brace";target=new Vector4(-35,-125,40,125);}
            else if(!ready){Phase="attachment_handoff";target=new Vector4(-40,-120,40,120);}
            else if(braking){Phase="input_brake";target=new Vector4(-100,-155,100,155);lean=-travel*18;}
            else if(speed<3.1f){Phase="apex_prepare";target=new Vector4(-70,-155,70,155);lean=pressing?input*9:0;}
            else if(bottom>.80f&&speed>7){Phase="fast_bottom";target=travel>0?new Vector4(-70,-35,-25,-90):new Vector4(25,90,70,35);lean=-travel*13;}
            else if(pressing)
            {
                Phase="input_pump";
                target=input>0?new Vector4(-45,-115,85,155):new Vector4(-85,-155,45,115);
                lean=input*25;
            }
            else{Phase="coast";target=new Vector4(-18,-40,18,40);lean=-travel*Mathf.Clamp(speed,0,10);}
            float blend=1-Mathf.Exp(-dt/.10f);
            angles=Vector4.Lerp(angles,target,blend);torso=Mathf.Lerp(torso,lean,blend);
            weight=Mathf.MoveTowards(weight,1,dt/.18f);
        }
        public float TorsoRadians(bool flipped)=>torso*Mathf.Deg2Rad*(flipped?-1:1);
        public void Draw(SpriteRenderer source,Vector4 landmarks,float bodyRotation)
        {
            if(weight<=.001f){Hide();return;}
            float width=landmarks.z;
            Vector2 neck=new Vector2(landmarks.x,landmarks.y);
            // Angles are world-input aware. Mirror only at the sprite coordinate boundary.
            Vector4 local=source.flipX?new Vector4(-angles.z,-angles.w,-angles.x,-angles.y):angles;
            DrawArm(left,source,neck,width,-1,local.x,local.y,bodyRotation,.83f);
            DrawArm(right,source,neck,width,1,local.z,local.w,bodyRotation,1);
            LeftHand=left.GetPosition(2);RightHand=right.GetPosition(2);
        }
        void DrawArm(LineRenderer line,SpriteRenderer source,Vector2 neck,float width,float side,
            float upper,float fore,float rotation,float shade)
        {
            var shoulder=neck+new Vector2(side*width*.17f,-width*.09f);
            var elbow=shoulder+Down(upper)*(width*.34f);
            var hand=elbow+Down(fore)*(width*.34f);
            line.enabled=true;line.sortingLayerID=source.sortingLayerID;line.sortingOrder=source.sortingOrder+(side<0?-1:1);
            float worldWidth=width*Mathf.Abs(source.transform.lossyScale.x)*.15f;
            line.startWidth=worldWidth;line.endWidth=worldWidth*.87f;
            line.textureScale=new Vector2(1/Mathf.Max(.01f,worldWidth*2),1);
            Color color=new Color(shade,shade,shade,weight);
            line.startColor=line.endColor=color;
            line.SetPosition(0,World(shoulder));line.SetPosition(1,World(elbow));line.SetPosition(2,World(hand));
            Vector3 World(Vector2 p)
            {
                Vector2 d=p-neck;float s=Mathf.Sin(rotation),c=Mathf.Cos(rotation);
                p=neck+new Vector2(c*d.x-s*d.y,s*d.x+c*d.y);
                if(source.flipX)p.x=-p.x;
                return source.transform.TransformPoint(p);
            }
        }
        static Vector2 Down(float degrees){float a=degrees*Mathf.Deg2Rad;return new Vector2(Mathf.Sin(a),-Mathf.Cos(a));}
        public void Hide(){if(left)left.enabled=false;if(right)right.enabled=false;}
        void OnDisable()=>Hide();
        void OnDestroy(){if(yarn)Destroy(yarn);}
    }
}

