using System;
using System.Collections;
using System.Collections.Generic;
using System.IO;
using HimoHitoA2Proof;
using UnityEngine;

namespace HimoHito
{
    public sealed class ConnectionGestureCapture:MonoBehaviour
    {
        A2Fixture f;A2InputDriver input;PlayerMotionPresentation motion;RopeBodyVisual art;
        readonly List<Sample> samples=new List<Sample>();readonly List<Check> checks=new List<Check>();
        bool recording;string phase="standing";int frame;float started;
        [Serializable]public class Check{public string name;public bool pass;public Check(string n,bool p){name=n;pass=p;}}
        [Serializable]public class Result{public string candidate,method="Automatic original API and existing input fields; explicit offline 30fps. No OS/Human input.";public List<Sample> samples;public List<Check> checks;public bool finished;}
        [Serializable]public class Sample
        {
            public int frame,bridges,selected,knotCount;public float time,fixedTime,remaining,input,colliderBottom,floorY,span,ropeLength,slack,soleY,crownError,contactError,speed,armWeight,ortho;
            public bool attached,grounded,floorFound,bodySimulated,failure,paused,secondCandidate,thirdCandidate;
            public string phase,sprite,gesture;public Vector2 root,velocity,anchor,crown,ropeFirst,ropeLast;
            public Vector3 camera,leftHand,rightHand;public Vector4 armAngles;
        }
        IEnumerator Wait(float s){yield return new WaitForSeconds(s);}
        void CheckResult(string n,bool p){checks.Add(new Check(n,p));Debug.Log("CONNECTION_REVIEW "+n+" "+p);}
        IEnumerator Start()
        {
            if(PlayerPresentationProof.Manual)yield break;
            while(!(f=A2Fixture.Instance)||!f.Ready||!(motion=f.Body.GetComponent<PlayerMotionPresentation>()))yield return null;
            art=f.Body.GetComponent<RopeBodyVisual>();
            if(PlayerPresentationProof.ThirdCandidate)while(!motion.ActiveArms)yield return null;
            // Same fixed-clock barrier for both candidates; component Start order is not an input variable.
            while(Time.time<1.0f)yield return null;
            input=f.gameObject.AddComponent<A2InputDriver>();
            f.Write("CaptureConfig.json",new A2Fixture.Config(f));
            if(A2Fixture.Arg("-gestureCase")=="input_response"){yield return InputResponse();yield break;}
            started=Time.time;recording=true;StartCoroutine(Frames());
            yield return Wait(.65f);
            phase="ground_attach_slack";
            CheckResult("Ground attach existing length6",f.Rope.TryAttach(GameObject.Find(A2Fixture.SwingNames[0]).transform.position));
            yield return Wait(.95f);
            phase="input_acceleration";input.Move=1;
            bool positive=false,right=false,left=false;float deadline=Time.time+12;
            while(Time.time<deadline&&!f.Respawn.IsFailureVisible)
            {
                Vector2 v=f.Body.linearVelocity;
                if(v.x>2)positive=true;
                if(positive&&!right&&v.x<0){right=true;phase=f.Mover.IsGrounded?"floor_contact_turn":"right_turn";}
                if(right&&!left&&v.x>0){left=true;phase=f.Mover.IsGrounded?"floor_contact_turn":"left_turn";}
                input.Move=v.x<-.05f?-1:1;
                Vector2 d=f.Body.position-f.Rope.AnchorPoint;
                float angle=Mathf.Atan2(d.x,-d.y)*Mathf.Rad2Deg;
                if(left&&angle>=36&&v.x>0&&v.y>0)break;
                yield return new WaitForFixedUpdate();
            }
